import { dirname } from 'node:path';
import { preDeploy } from '../../actions/blueprints/pre-deploy.js';
import { getStack, updateStack } from '../../actions/blueprints/stacks.js';
import { waitForOperation } from '../../actions/blueprints/wait-for-operation.js';
import { checkUserPermission } from '../../actions/sanity/access.js';
import { getClientMetadata } from '../../utils/blueprints/deploy-metadata.js';
import { extractDurableConfig } from '../../utils/blueprints/extract-durable-config.js';
import { createHintCollector } from '../../utils/blueprints/hints.js';
import { stampInstallationConfigVersion } from '../../utils/blueprints/stamp-installation-config-version.js';
import { createWaitFor } from '../../utils/blueprints/wait-for.js';
import { formatStudioUrls } from '../../utils/display/blueprints-formatting.js';
import { check, niceId, severe } from '../../utils/display/presenters.js';
import { CODE_OPERATION_UNCONFIRMED, EXIT_OPERATION_UNCONFIRMED } from '../../utils/exit-codes.js';
import { runCommand } from '../../utils/package-manager.js';
import { styleText } from '../../utils/style-text.js';
import { createTracedFetch } from '../../utils/traced-fetch.js';
import { getWarnings } from '../../utils/warnings.js';
export async function blueprintDeployCore(options) {
    const { bin = 'sanity', log: logger, auth, stackId, scopeType, scopeId, deployedStack, blueprint, cliVersion, flags, } = options;
    const { verbose } = flags;
    const noWait = flags['no-wait'] || false;
    const stackName = flags['new-stack-name'] ?? deployedStack.name;
    const installer = flags['fn-installer'] || undefined;
    const blueprintFileDir = dirname(blueprint.fileInfo.blueprintFilePath);
    const workspaceWarnings = getWarnings({ dir: blueprintFileDir });
    logger(`Deploying "${stackName}" ${niceId(deployedStack.id)}...`);
    try {
        const fetchFn = createTracedFetch(logger);
        const { ok: checkOk, stack: currentStack } = await getStack({ stackId, auth, fetchFn });
        if (!checkOk) {
            return { success: false, error: 'Failed to check current Stack status' };
        }
        const operationStatus = currentStack.recentOperation?.status;
        if (operationStatus === 'QUEUED' || operationStatus === 'IN_PROGRESS') {
            return {
                success: false,
                error: 'A Stack operation is already in progress.',
                suggestions: [
                    `Run \`${runCommand(bin)} blueprints info\` to check operation status.`,
                    'Wait for the current operation to complete, then try again.',
                ],
            };
        }
        const resources = [...blueprint.resources];
        await extractDurableConfig(resources, blueprintFileDir);
        await stampInstallationConfigVersion(resources, blueprintFileDir);
        let spinner;
        const preDeployResult = await preDeploy({
            scopeType,
            scopeId,
            resources, // mutated by preDeploy
            stackId,
            stackName,
            auth,
            blueprintFileDir,
            installer,
            bin,
            fetchFn,
            waitForFn: createWaitFor({ bin, log: logger, verbose }),
            onAssetEvent: createAssetEventHandler(logger),
            onPreDeployStackStart() {
                spinner = logger.ora('Starting pre-deploy...').start();
            },
            onPreDeployStackFail() {
                spinner.fail(`${styleText('red', 'Failed')} to complete Stack pre-deployment`);
            },
            onPreDeployStackDone() {
                spinner.stop().clear();
            },
            onPreDeployOperationStart() {
                logger(styleText('dim', 'Stack pre-deployment progress:'));
                logger('');
            },
            onPreDeployOperationDone() {
                logger(styleText(['bold', 'green'], 'Stack pre-deployment completed!'));
            },
        });
        if (!preDeployResult?.success)
            return preDeployResult;
        const metadata = {
            client: getClientMetadata({ cliVersion, dir: blueprintFileDir }),
            resources: preDeployResult.resourceMetadata,
        };
        const deploySpinner = logger.ora('Deploying...').start();
        const { ok: deployOk, stack, error: deployError, requestId, } = await updateStack({
            stackId,
            stackMutation: {
                scopeType,
                scopeId,
                name: stackName,
                document: { resources },
                userMessage: flags.message,
                metadata,
            },
            auth,
            fetchFn,
        });
        if (!deployOk) {
            deploySpinner.fail(`${styleText('red', 'Failed')} to update Stack deployment`);
            const hints = createHintCollector(bin);
            if (deployError) {
                hints.inspectMessage(deployError);
            }
            return {
                success: false,
                error: deployError || 'Failed to update Stack deployment',
                requestId,
                suggestions: [
                    ...hints.getSuggestions(),
                    `Run \`${runCommand(bin)} blueprints plan\` to preview changes before deploying.`,
                    `Run \`${runCommand(bin)} blueprints doctor\` to check your configuration.`,
                ],
            };
        }
        deploySpinner.stop().clear();
        if (requestId)
            logger.verbose(styleText('dim', `Request ID: ${requestId}`));
        const legacyPermissionsNoticePromise = CHECK_LEGACY_DEPLOY_PERMISSION
            ? checkLegacyDeployPermission({
                auth,
                scopeType,
                scopeId,
                log: logger,
            })
            : Promise.resolve(null);
        if (noWait) {
            logger(styleText(['bold', 'green'], 'Stack deployment started!'));
            logger(`Use \`${runCommand(bin)} blueprints info\` to check status`);
            if (requestId && !verbose)
                logger(styleText('dim', `Request ID: ${requestId}`));
            const legacyWarning = await legacyPermissionsNoticePromise;
            const warnings = [...(legacyWarning ? [legacyWarning] : []), ...workspaceWarnings];
            return {
                success: true,
                json: { stackId, resources, requestId },
                data: { resources },
                warnings: warnings.length ? warnings : undefined,
            };
        }
        logger(styleText('dim', 'Stack deployment progress:'));
        logger('');
        const outcome = await waitForOperation({
            stackId,
            operationId: stack.operationId,
            auth,
            log: logger,
            bin,
            verbose,
            progressNoun: 'deployment',
        });
        if (outcome.type === 'completed') {
            logger(styleText(['bold', 'green'], 'Stack deployment completed!'));
            for (const line of formatStudioUrls(stack.resources))
                logger(line);
            const legacyWarning = await legacyPermissionsNoticePromise;
            const warnings = [...(legacyWarning ? [legacyWarning] : []), ...workspaceWarnings];
            return {
                success: true,
                json: { stackId, resources, requestId },
                data: { resources },
                warnings: warnings.length ? warnings : undefined,
            };
        }
        if (outcome.type === 'unconfirmed') {
            return {
                success: false,
                error: `Stack deployment was accepted but completion could not be confirmed${outcome.error ? ` (${outcome.error})` : ''}.`,
                requestId,
                code: CODE_OPERATION_UNCONFIRMED,
                exitCode: EXIT_OPERATION_UNCONFIRMED,
                suggestions: [
                    'The deployment may or may not have finished on Sanity servers.',
                    `Run \`${runCommand(bin)} blueprints info\` to check status.`,
                    `Run \`${runCommand(bin)} blueprints logs --watch\` to keep streaming logs.`,
                ],
            };
        }
        return {
            success: false,
            error: 'Stack deployment failed',
            requestId,
            suggestions: [
                ...outcome.logHints,
                'Review the deployment output above for error details.',
                `Run \`${runCommand(bin)} blueprints logs --verbose\` for more context.`,
                `Run \`${runCommand(bin)} blueprints plan\` to identify issues with your Blueprint.`,
            ],
        };
    }
    catch (error) {
        const errorMessage = error instanceof Error ? error.message : String(error);
        return { success: false, error: errorMessage };
    }
}
function createAssetEventHandler(logger) {
    let spinner;
    const results = [];
    return (event) => {
        switch (event.type) {
            case 'progress': {
                const { completed, total, slow } = event.progress;
                const text = [
                    `Processing assets (${completed}/${total})`,
                    slow ? ', this can take a moment' : '',
                ].join('');
                if (spinner)
                    spinner.text = text;
                else
                    spinner = logger.ora(text).start();
                return;
            }
            case 'result': {
                results.push(event.result);
                return;
            }
            case 'complete': {
                spinner?.stop();
                spinner = undefined;
                break;
            }
        }
        // done. print report
        for (const result of results) {
            const { resource } = result;
            if (!result.success) {
                const summary = result.failureKind === 'upload'
                    ? `Failed uploading ${resource.name} asset`
                    : `Failed processing ${resource.name} asset`;
                logger(` ${severe(summary)}`);
                logger.error(`   ${result.error}`);
                continue;
            }
            const r = resource;
            const assetParameter = String(r[result.assetParameter]);
            logger(` ${check(`${resource.name} ${niceId(assetParameter)}`)}`);
            logger(`   Source: ${assetParameter}`);
            if (result.hash) {
                const hash = result.hash;
                const h = hash.length > 24 ? `${hash.slice(0, 8)}...${hash.slice(-12)}` : hash;
                logger.verbose(`   Hash: ${h}`);
            }
            if (result.exists)
                logger.verbose('   Asset unchanged');
        }
    };
}
const CHECK_LEGACY_DEPLOY_PERMISSION = false;
const BLUEPRINTS_PERMISSION_ENFORCEMENT_DATE = 'July 1, 2026';
async function checkLegacyDeployPermission({ auth, scopeType, scopeId, log, }) {
    const requiredPermission = scopeType === 'organization' ? 'sanity.blueprints.deploy' : 'sanity.project.blueprints.deploy';
    try {
        const result = await checkUserPermission({
            auth,
            resourceType: scopeType,
            resourceId: scopeId,
            permission: requiredPermission,
            logger: log,
        });
        if (!result.ok) {
            log.verbose(`Failed to check ${requiredPermission}: ${result.error ?? 'unknown error'}`);
            return null;
        }
        if (result.hasPermission)
            return null;
        return {
            code: 'Legacy deploy permission',
            suggestions: [
                `This deploy used a legacy permission. Starting ${BLUEPRINTS_PERMISSION_ENFORCEMENT_DATE}, deploys will require the "${requiredPermission}" permission.`,
                scopeType === 'project'
                    ? 'Ask a project administrator to add you to a role with Blueprint deploy access: Administrator, Developer, or Blueprints Deployer. For CI, use a Blueprints Deployer API token.'
                    : 'Ask an organization administrator to grant you the Administrator role. For CI, use a Blueprints Deployer API token created by someone with access to this organization.',
            ],
        };
    }
    catch (err) {
        log.verbose(`Failed to check ${requiredPermission}: ${err instanceof Error ? err.message : String(err)}`);
        return null;
    }
}
